import * as React from 'react'
import { cn } from '@/lib/utils'
import { useMergedRefs } from '@/lib/merge-refs'

export interface ToggleGroupOption<T extends string = string> {
  value: T
  label: string
  /**
   * Optional icon element rendered above the label. The DS avoids bundling an
   * icon library so the caller passes the icon node directly
   * (e.g. `<Sun size={20} weight="regular" />`).
   */
  icon?: React.ReactNode
}

export interface ToggleGroupProps<T extends string = string> {
  options: ToggleGroupOption<T>[]
  value: T
  onChange: (value: T) => void
  className?: string
}

/**
 * Segmented control (toggle group). Presentational only -- no theme or
 * sort logic inside. Pass translated option labels; the DS is i18n-free.
 *
 * Active option renders with the accent colour. A check mark is shown in the
 * top-right corner of the selected tile. Supports an optional icon per option
 * (pass icon ReactNodes; the DS does not bundle an icon library).
 *
 * Layout: `grid` with `grid-cols-{n}` auto-sized by count (handled via
 * inline style). Callers may override with `className`.
 *
 * Usage:
 *
 * ```tsx
 * const themeOptions = [
 *   { value: 'light', label: t('settings.light'), icon: <Sun size={20} weight="regular" /> },
 *   { value: 'dark',  label: t('settings.dark'),  icon: <Moon size={20} weight="regular" /> },
 *   { value: 'system', label: t('settings.system'), icon: <Desktop size={20} weight="regular" /> },
 * ]
 *
 * <ToggleGroup options={themeOptions} value={theme} onChange={setTheme} />
 * ```
 */
function ToggleGroupInner<T extends string = string>(
  { options, value, onChange, className }: ToggleGroupProps<T>,
  ref: React.ForwardedRef<HTMLDivElement>,
) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const mergedRef = useMergedRefs(containerRef, ref)

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (!options.length) return
      const currentIndex = options.findIndex((o) => o.value === value)

      let nextIndex: number | null = null
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
        nextIndex = currentIndex < options.length - 1 ? currentIndex + 1 : 0
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
        nextIndex = currentIndex > 0 ? currentIndex - 1 : options.length - 1
      }

      if (nextIndex !== null) {
        e.preventDefault()
        const next = options[nextIndex]
        onChange(next.value as T)
        const btn = containerRef.current?.querySelectorAll<HTMLElement>('[role="radio"]')[nextIndex]
        btn?.focus()
      }
    },
    [options, value, onChange]
  )

  return (
    <div
      ref={mergedRef}
      role="radiogroup"
      onKeyDown={handleKeyDown}
      className={cn('grid gap-3', className)}
      style={{ gridTemplateColumns: `repeat(${options.length}, minmax(0, 1fr))` }}
    >
      {options.map((option) => {
        const isSelected = value === option.value
        return (
          <button
            key={option.value}
            role="radio"
            aria-checked={isSelected}
            tabIndex={isSelected ? 0 : -1}
            type="button"
            onClick={() => onChange(option.value as T)}
            className={cn(
              'wj-focus-ring relative px-3 py-3 rounded-xl border-2 transition-all text-sm font-medium',
              option.icon ? 'flex flex-col items-center gap-1.5' : 'flex items-center justify-center',
              isSelected
                ? 'bg-[var(--color-accent-500)] border-[var(--color-accent-500)] text-[var(--color-accent-foreground)] shadow-md'
                : [
                    'bg-[var(--color-surface-light)] border-[var(--color-border-light)]',
                    'text-[var(--color-text-secondary-light)]',
                    'hover:border-[var(--color-accent-400)]',
                    'dark:bg-[var(--color-surface-dark)] dark:border-[var(--color-border-dark)]',
                    'dark:text-[var(--color-text-secondary-dark)]',
                    'dark:hover:border-[var(--color-neutral-500)]',
                  ]
            )}
          >
            {isSelected && (
              <span className="absolute top-1.5 end-1.5">
                {/* Inline checkmark -- avoids icon library dependency */}
                <svg
                  viewBox="0 0 12 12"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  aria-hidden
                  className="w-3 h-3"
                >
                  <path d="M2 6l3 3 5-5" />
                </svg>
              </span>
            )}
            {option.icon && (
              <span aria-hidden>
                {option.icon}
              </span>
            )}
            <span>{option.label}</span>
          </button>
        )
      })}
    </div>
  )
}

// forwardRef erases the generic type parameter, so re-assert it on the exported
// component: ToggleGroup keeps `value`/`onChange` typed to the option union AND
// forwards a ref to the radiogroup element.
const ToggleGroupWithRef = React.forwardRef(ToggleGroupInner)
ToggleGroupWithRef.displayName = 'ToggleGroup'
export const ToggleGroup = ToggleGroupWithRef as <T extends string = string>(
  props: ToggleGroupProps<T> & { ref?: React.Ref<HTMLDivElement> },
) => React.ReactElement
